    facts: {
      de: ["Der Gipfel ist 1.561 Meter hoch.", "Die Entwicklung für die Olympischen Spiele war umstritten wegen der Abholzung von 500 Jahre alten Bäumen.", "Beherbergt ein Erholungsgebiet mit Wanderwegen und Campingplätzen.", "Traditionell als heiliger Berg verehrt."],
      hu: ["A csúcs 1561 méter magas.", "Az olimpiai fejlesztés ellentmondásos volt az 500 éves fák kivágása miatt.", "Egy rekreációs területnek ad otthont túraútvonalakkal és kempingekkel.", "Hagyományosan szent hegyként tisztelik."],
      ro: ["Vârful are 1.561 de metri înălțime.", "Dezvoltarea pentru Jocurile Olimpice a fost controversată din cauza tăierii copacilor de 500 de ani.", "Găzduiește o zonă de agrement cu trasee de drumeție și locuri de campare.", "Considerat în mod tradițional un munte sacru."],
      en: ["The peak is 1,561 meters high.", "The development for the Olympics was controversial due to the felling of 500-year-old trees.", "Home to a recreational forest with trails and campsites.", "Traditionally revered as a sacred mountain."],
      es: ["El pico tiene 1.561 metros de altura.", "El desarrollo para los Juegos Olímpicos fue controvertido debido a la tala de árboles de 500 años.", "Alberga un área de recreo con rutas de senderismo y campings.", "Tradicionalmente venerada como una montaña sagrada."],
      pt: ["O cume tem 1.561 metros de altura.", "O desenvolvimento para os Jogos Olímpicos foi controverso devido ao abate de árvores com 500 anos.", "Abriga uma área de lazer com trilhos e parques de campismo.", "Tradicionalmente venerada como uma montanha sagrada."],
      fr: ["Le sommet culmine à 1 561 mètres.", "Le développement pour les Jeux olympiques a été controversé en raison de l'abattage d'arbres vieux de 500 ans.", "Abrite une zone de loisirs avec des sentiers de randonnée et des campings.", "Traditionnellement vénérée comme une montagne sacrée."],
    }, image: "/poi-images/gariwangsan-mountain-relief-v2.webp",
    descriptionAdvanced: {
      de: "Der Gariwangsan ist ein markanter Berg in der Provinz Gangwon in Südkorea mit einer Höhe von 1561 Metern über dem Meeresspiegel. Er erlangte internationale Bekanntheit als Austragungsort der alpinen Skiwettbewerbe während der Olympischen Winterspiele 2018 in Pyeongchang. Das Bergmassiv ist für seine ökologische Bedeutung bekannt, da es seit der Joseon-Dynastie als geschützter königlicher Wald galt und seltene Baumarten wie die Koreatanne beherbergt. Historisch gesehen war der Zugang zum Berg streng reglementiert, um die natürlichen Ressourcen zu schonen und spirituelle Stätten zu bewahren. Heute ist das Gebiet ein beliebtes Ziel für Wanderer, die die weiten Aussichten über das Taebaek-Gebirge und die unberührte Natur schätzen. Trotz der Kontroversen um den Bau der olympischen Skipisten bleibt der Berg ein Symbol für die alpine Wildnis der Region. Die Flora umfasst zahlreiche endemische Pflanzenarten, die typisch für die kühleren Hochlagen der Koreanischen Halbinsel sind.",
      hu: "A Gariwangsan Dél-Korea Gangwon tartományában található, 1561 méteres magasságával az ország egyik legjelentősebb hegycsúcsa. Nemzetközi hírnévre a 2018-as pjongcsangi téli olimpiai játékok idején tett szert, amikor itt rendezték meg az alpesi síversenyeket. A hegység ökológiai szempontból kiemelkedő, mivel a Csoszon-dinasztia idejétől kezdve védett királyi erdőnek számított, és olyan ritka fafajoknak ad otthont, mint a koreai jegenyefenyő. Történelmileg a hegyhez való hozzáférés korlátozott volt a természeti erőforrások megőrzése és a spirituális helyszínek védelme érdekében. Napjainkban a túrázók körében kedvelt célpont, akik a Taebaek-hegységre nyíló panoráma és a vadregényes táj miatt látogatják. Az olimpiai sípályák kialakítása körüli környezetvédelmi viták ellenére a Gariwangsan továbbra is a régió alpesi természetének fontos szimbóluma marad. Flórája gazdag endemikus fajokban, amelyek a félsziget hűvösebb magaslataira jellemzőek.",
      ro: "Muntele Gariwangsan este situat în provincia Gangwon din Coreea de Sud, având o înălțime de 1561 de metri deasupra nivelului mării. A câștigat recunoaștere internațională ca loc de desfășurare a probelor de schi alpin în timpul Jocurilor Olimpice de Iarnă din 2018 de la Pyeongchang. Masivul muntos este renumit pentru importanța sa ecologică, fiind considerat o pădure regală protejată încă din timpul dinastiei Joseon, adăpostind specii rare de arbori precum bradul coreean. Din punct de vedere istoric, accesul pe munte a fost strict reglementat pentru a proteja resursele naturale și siturile spirituale. Astăzi, zona este o destinație populară pentru alpiniști și turiști care apreciază priveliștile vaste asupra lanțului muntos Taebaek și natura virgină. În ciuda controverselor legate de construcția pârtiilor olimpice, Gariwangsan rămâne un simbol al sălbăticiei alpine din regiune. Flora sa include numeroase specii de plante endemice, specifice zonelor înalte și reci ale peninsulei coreene.",
      en: "Gariwangsan Mountain is a prominent peak located in Gangwon Province, South Korea, standing at an elevation of 1,561 meters above sea level. It gained international fame as the venue for alpine skiing events during the 2018 Pyeongchang Winter Olympics. The mountain massif is renowned for its ecological significance, having been designated as a protected royal forest since the Joseon Dynasty, harboring rare tree species such as the Korean fir. Historically, access to the mountain was strictly regulated to preserve royal resources and maintain spiritual sites. Today, the area is a popular destination for hikers who appreciate the expansive views of the Taebaek Mountains and the pristine natural environment. Despite the environmental debates surrounding the construction of Olympic ski runs, Gariwangsan remains a symbol of the region's alpine wilderness. Its flora includes numerous endemic plant species typical of the cooler high-altitude regions of the Korean Peninsula.",
      es: "Gariwangsan es una montaña en la provincia de Gangwon-do, Corea del Sur, con una altitud de 1.561 metros. Es el pico más alto de las montañas Taebaek. La montaña es conocida por sus extensos pastos alpinos y el bosque Gariwang, una reserva de la biosfera de la UNESCO. La región es una importante cuenca de captación de agua. La vegetación incluye bosques de coníferas subalpinos. La montaña es popular entre senderistas y ciclistas de montaña. En invierno, hay estaciones de esquí.",
      pt: "Gariwangsan é uma montanha na província de Gangwon-do, na Coreia do Sul, com uma altitude de 1.561 metros. É o pico mais alto das montanhas Taebaek. A montanha é conhecida pelas suas extensas pastagens alpinas e pela floresta Gariwang, uma reserva da biosfera da UNESCO. A região é uma importante bacia de captação de água. A vegetação inclui florestas de coníferas subalpinas. A montanha é popular entre caminhantes e ciclistas de montanha. No inverno, existem estações de esqui.",
      fr: "Gariwangsan est une montagne dans la province de Gangwon-do, en Corée du Sud, avec une altitude de 1 561 mètres. C'est le plus haut sommet des montagnes Taebaek. La montagne est connue pour ses vastes pâturages alpins et la forêt de Gariwang, une réserve de biosphère de l'UNESCO. La région est un bassin versant important. La végétation comprend des forêts de conifères subalpines. La montagne est populaire auprès des randonneurs et des vététistes. En hiver, il y a des stations de ski.",
    },
