      pt: ["Famosa pelo festival anual da erva prateada no outono.", "O cume tem 1.119 metros de altura.", "O contraste entre as encostas arborizadas e o cume relvado é único.", "Oferece uma paisagem deslumbrante no outono."],
      fr: ["Célèbre pour le festival annuel de l'herbe argentée en automne.", "Le sommet culmine à 1 119 mètres.", "Le contraste entre les pentes boisées et le sommet herbeux est unique.", "Offre un paysage à couper le souffle en automne."],
